/**
 * Real local-only event runner. Opens wallets using Keycloak OIDC and sends
 * WagerTransactionRequested envelopes through the provisioned SQS FIFO queue.
 * It intentionally cannot publish outbound integration events directly:
 * WagerTransactionProcessed/Rejected/PendingReference/WalletBalanceChanged
 * are exclusively generated by the application within the SQL transaction.
 */
import { randomUUID } from 'node:crypto';
import { setTimeout as sleep } from 'node:timers/promises';
import { SendMessageCommand } from '@aws-sdk/client-sqs';
import { MikroORM } from '@mikro-orm/postgresql';
import config from '../src/mikro-orm.config.js';
import { sqsClient, sqsQueueUrl } from '../src/events/sqs-client.js';
import { parseWagerRequest } from '../src/events/wager-request.js';
import { WagerTransactionKind as Kind } from '../src/domain/wager-transaction.js';
import type { WagerCommand } from '../src/application/wager-contracts.js';

type ExternalKind = Exclude<Kind, Kind.Opening>;
type Wallet = { id: string; playerId: string; balance: { amount: string; currency: string }; version: number };
type Transaction = { id: string; status: string; failureCode?: string; result?: { balance: { amount: string }; walletVersion: number } };
type OutboxRow = { event_type: string; published_at: Date | null; payload: { eventType: string; aggregateId: string; data: Record<string, unknown> } };
type Ledger = { items: Array<{ direction: string; money: { amount: string } }> };
type Reconciled = { consistent: boolean; calculatedBalance: { amount: string } };

const apiUrl = (process.env.LOCAL_API_URL ?? 'http://127.0.0.1:3000').replace(/\/$/, '');
const idpUrl = (process.env.LOCAL_IDP_URL ?? 'http://keycloak:8080').replace(/\/$/, '');
const providerId = process.env.LOCAL_PROVIDER_ID ?? 'provider-a';
const secret = process.env.LOCAL_PROVIDER_SECRET ?? 'local-provider-a-change-me';
const timeoutMs = Number(process.env.LOCAL_VERIFY_TIMEOUT_MS ?? 90000);

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error('LOCAL_VERIFY: ' + message);
}
function ensureLocal(): void {
  assert(process.env.NODE_ENV !== 'production', 'This command is disabled in production');
  assert(
    /^http:\/\/(?:aws-emulator|localhost|127\.0\.0\.1):4566\/?$/.test(
      process.env.SQS_ENDPOINT_URL ?? '',
    ),
    'A local SQS emulator endpoint is required; refusing remote queue access',
  );
  assert(Number.isSafeInteger(timeoutMs) && timeoutMs >= 1000, 'Invalid verify timeout');
}
async function authenticate(): Promise<string> {
  const response = await fetch(`${idpUrl}/realms/wagering/protocol/openid-connect/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: providerId,
      client_secret: secret,
    }),
  });
  assert(response.ok, `Keycloak token endpoint returned HTTP ${response.status}`);
  const token = (await response.json()) as { access_token?: unknown };
  assert(typeof token.access_token === 'string', 'Missing signed OAuth access token');
  return token.access_token;
}
async function request<T>(
  path: string,
  token: string,
  method: 'GET' | 'POST' = 'GET',
  data?: unknown,
): Promise<{ status: number; data: T }> {
  const response = await fetch(apiUrl + path, {
    method,
    headers: {
      Authorization: `Bearer ${token}`,
      ...(data === undefined ? {} : { 'Content-Type': 'application/json' }),
    },
    ...(data === undefined ? {} : { body: JSON.stringify(data) }),
    signal: AbortSignal.timeout(10000),
  });
  const body = (await response.json()) as T;
  return { status: response.status, data: body };
}
async function openWallet(token: string, amount = '100.00'): Promise<Wallet> {
  const response = await request<Wallet>('/wallets', token, 'POST', {
    playerId: randomUUID(),
    initialBalance: { amount, currency: 'BRL' },
  });
  assert(response.status === 201, `Could not open wallet: HTTP ${response.status}`);
  assert(response.data.id && response.data.playerId, 'Opening response lacks wallet identity');
  return response.data;
}
function command(
  wallet: Pick<Wallet, 'id' | 'playerId'>,
  kind: ExternalKind,
  amount: string,
  externalTransactionId = randomUUID(),
  referenceExternalTransactionId?: string,
): WagerCommand {
  return {
    providerId,
    externalTransactionId,
    idempotencyKey: `${providerId}:${externalTransactionId}`,
    walletId: wallet.id,
    playerId: wallet.playerId,
    roundId: 'local-' + wallet.id.slice(0, 8),
    gameId: 'local-events',
    kind,
    money: { amount, currency: 'BRL' },
    ...(referenceExternalTransactionId ? { referenceExternalTransactionId } : {}),
  };
}
async function send(
  sqs: ReturnType<typeof sqsClient>,
  queueUrl: string,
  cmd: WagerCommand,
): Promise<{ messageId: string; externalTransactionId: string }> {
  const envelope = {
    messageId: randomUUID(),
    type: 'WagerTransactionRequested',
    occurredAt: new Date().toISOString(),
    data: cmd,
  };
  // Use the exact production parser before sending, not a guessed schema.
  parseWagerRequest(JSON.stringify(envelope));
  await sqs.send(
    new SendMessageCommand({
      QueueUrl: queueUrl,
      MessageBody: JSON.stringify(envelope),
      MessageGroupId: cmd.walletId,
      MessageDeduplicationId: envelope.messageId,
    }),
  );
  return { messageId: envelope.messageId, externalTransactionId: cmd.externalTransactionId };
}
async function waitForTransaction(
  token: string,
  externalId: string,
  expectedStatus: string,
): Promise<Transaction> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const response = await request<Transaction>(
      `/providers/${encodeURIComponent(providerId)}/wagering/transactions/${encodeURIComponent(externalId)}`,
      token,
    );
    if (response.status === 200) {
      if (expectedStatus === 'ANY' || response.data.status === expectedStatus) return response.data;
      assert(
        response.data.status === 'PENDING_REFERENCE' && expectedStatus === 'PROCESSED',
        `Wager ${externalId} reached unexpected state ${response.data.status}, wanted ${expectedStatus}`,
      );
    } else {
      assert(response.status === 404, `Wager lookup failed: HTTP ${response.status}`);
    }
    await sleep(350);
  }
  throw new Error(`Timed out waiting for ${externalId} => ${expectedStatus}`);
}
async function outbox(walletId: string, orm: MikroORM): Promise<OutboxRow[]> {
  return orm.em.fork().execute<OutboxRow[]>(
    'select event_type,published_at,payload from outbox_messages where aggregate_id=?::uuid order by publication_sequence',
    [walletId],
  );
}
async function verifyPublished(walletId: string, orm: MikroORM, count: number): Promise<OutboxRow[]> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const events = await outbox(walletId, orm);
    if (events.length === count && events.every((event) => event.published_at !== null)) {
      return events;
    }
    assert(events.length <= count, 'Unexpected duplicate Outbox records for the same wallet');
    await sleep(350);
  }
  const events = await outbox(walletId, orm);
  throw new Error(`Outbox publishing timed out: ${events.length}/${count} events, ${events.filter((e) => e.published_at).length} published`);
}
async function demo(token: string): Promise<void> {
  const wallet = await openWallet(token);
  const sqs = sqsClient();
  const orm = await MikroORM.init(config);
  try {
    const queue = await sqsQueueUrl(
      sqs,
      process.env.SQS_WAGER_TRANSACTIONS_URL,
      process.env.SQS_WAGER_TRANSACTIONS_QUEUE_NAME ?? 'wager-transactions.fifo',
    );
    async function step(cmd: WagerCommand, status: string, failureCode?: string): Promise<Transaction> {
      await send(sqs, queue, cmd);
      const tx = await waitForTransaction(token, cmd.externalTransactionId, status);
      if (failureCode) assert(tx.failureCode === failureCode, `Expected ${failureCode}, got ${tx.failureCode}`);
      return tx;
    }
    const bet = command(wallet, Kind.Bet, '20.00');
    await step(bet, 'PROCESSED');
    await step(command(wallet, Kind.Win, '5.00'), 'PROCESSED');
    await step(command(wallet, Kind.Loss, '1.00'), 'PROCESSED');
    const refund = command(wallet, Kind.Refund, '20.00', randomUUID(), bet.externalTransactionId);
    await step(refund, 'PROCESSED');
    await step(command(wallet, Kind.Rollback, '20.00', randomUUID(), refund.externalTransactionId), 'PROCESSED');
    await step(command(wallet, Kind.Bet, '999.00'), 'REJECTED', 'INSUFFICIENT_FUNDS');

    // True out-of-order integration test: refund arrives before its BET.
    const futureBetExternalId = randomUUID();
    const pending = command(wallet, Kind.Refund, '10.00', randomUUID(), futureBetExternalId);
    await step(pending, 'PENDING_REFERENCE');
    await step(command(wallet, Kind.Bet, '10.00', futureBetExternalId), 'PROCESSED');
    await waitForTransaction(token, pending.externalTransactionId, 'PROCESSED');

    const w = await request<Wallet>(`/wallets/${wallet.id}`, token);
    assert(w.status === 200, 'Wallet read failed');
    assert(w.data.balance.amount === '85.00', `Expected 85.00, got ${w.data.balance.amount}`);
    assert(w.data.version === 7, `Expected version 7, got ${w.data.version}`);
    const ledger = await request<Ledger>(`/wallets/${wallet.id}/ledger?limit=20`, token);
    assert(ledger.status === 200 && ledger.data.items.length === 7, 'Expected 7 immutable ledger entries');
    const reconciled = await request<Reconciled>(
      `/wallets/${wallet.id}/reconciliation`,
      token,
      'POST',
      {},
    );
    assert(reconciled.status === 200 && reconciled.data.consistent, 'Ledger reconciliation failed');
    assert(reconciled.data.calculatedBalance.amount === '85.00', 'Reconciled balance mismatch');

    const published = await verifyPublished(wallet.id, orm, 17);
    const distribution = new Map<string, number>();
    for (const event of published) {
      assert(event.payload.eventType === event.event_type, 'Event type differs from SQL Outbox');
      assert(event.payload.aggregateId === wallet.id, 'Outbox aggregate mismatch');
      distribution.set(event.event_type, (distribution.get(event.event_type) ?? 0) + 1);
    }
    const expected = {
      WagerTransactionProcessed: 8,
      WalletBalanceChanged: 7,
      WagerTransactionRejected: 1,
      WagerTransactionPendingReference: 1,
    };
    for (const [kind, count] of Object.entries(expected)) {
      assert(distribution.get(kind) === count, `Expected ${count} events of ${kind}, got ${distribution.get(kind) ?? 0}`);
    }
    console.log(
      JSON.stringify(
        {
          outcome: 'passed',
          scenario: 'local-full-sqs-event-flow',
          walletId: wallet.id,
          processedKinds: ['OPENING', 'BET', 'WIN', 'LOSS', 'REFUND', 'ROLLBACK'],
          testedOutOfOrder: true,
          testedRejection: true,
          balance: w.data.balance,
          version: w.data.version,
          ledgerEntries: ledger.data.items.length,
          outboxPublished: published.length,
          eventTypes: Object.fromEntries(distribution),
          reconciliationConsistent: reconciled.data.consistent,
        },
        null,
        2,
      ),
    );
  } finally {
    sqs.destroy();
    await orm.close(true);
  }
}
async function main(): Promise<void> {
  ensureLocal();
  const [operation, ...args] = process.argv.slice(2);
  assert(operation, 'Usage: local-events.ts wallet [amount] | send KIND walletId playerId amount [reference] | demo');
  const token = await authenticate();
  if (operation === 'wallet') {
    console.log(JSON.stringify(await openWallet(token, args[0] ?? '100.00'), null, 2));
  } else if (operation === 'send') {
    const [name, walletId, playerId, amount, reference] = args;
    const kinds = ['BET', 'WIN', 'LOSS', 'REFUND', 'ROLLBACK'];
    assert(name && kinds.includes(name), 'KIND must be BET, WIN, LOSS, REFUND or ROLLBACK');
    assert(walletId && playerId && amount, 'Provide walletId playerId amount');
    const cmd = command(
      { id: walletId, playerId },
      name as ExternalKind,
      amount,
      randomUUID(),
      reference,
    );
    const sqs = sqsClient();
    try {
      const queue = await sqsQueueUrl(
        sqs,
        process.env.SQS_WAGER_TRANSACTIONS_URL,
        process.env.SQS_WAGER_TRANSACTIONS_QUEUE_NAME ?? 'wager-transactions.fifo',
      );
      const sent = await send(sqs, queue, cmd);
      const state = await waitForTransaction(token, cmd.externalTransactionId, 'ANY');
      console.log(JSON.stringify({ ...sent, kind: cmd.kind, status: state.status, transactionId: state.id }, null, 2));
    } finally {
      sqs.destroy();
    }
  } else if (operation === 'demo') {
    await demo(token);
  } else {
    throw new Error('Unknown operation: ' + operation);
  }
}
void main().catch((error: unknown) => {
  console.error('Local event flow failed:', error);
  process.exitCode = 1;
});
